
'use strict';
const $=s=>document.querySelector(s), KEY='transport-logistics-demo-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blankDraft=()=>({type:'hydro',work:'',comment:'',address:'',destination:'',cargo:'',weight:'',volume:'',day:'',time:'',hours:'3',km:'0',access:'',name:'',phone:'',photos:[],exampleFilled:false});
let db={orders:[],draft:blankDraft(),quotes:{},chats:{},role:'client'};
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.orders)){db={...db,...v,draft:{...blankDraft(),...v.draft}}}}catch{}
let role=db.role==='manager'?'manager':'client',photoBusy=false,toastTimer;const scrolls=new Map();
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{toast('Не удалось сохранить: освободите память браузера.');return false}}
function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4500)}
const types={hydro:'Гидроборт',freight:'Беларусь — Россия'};
const statuses={new:'На оценке',offer:'Цена предложена',accepted:'Условия приняты',question:'Есть вопрос',scheduled:'Перевозка согласована',completed:'Выполнено'};
const fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2});
const date=t=>new Date(t).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const badge=o=>`<span class="badge ${o.status}"><i class="dot"></i>${statuses[o.status]}</span>`;
function route(){let [page,id]=location.hash.slice(1).split('/');return {page:page||'home',id}}
if('scrollRestoration' in history)history.scrollRestoration='manual';
let currentHash=location.hash;
function go(path){scrolls.set(currentHash,$('#main').scrollTop);if(location.hash==='#'+path){render();$('#main').scrollTop=0}else location.hash=path}
function backPath(){const r=route();return r.page==='request'?(r.id==='contact'?'request':'home'):r.page==='order'?'orders':'home'}
function back(){if(document.querySelector('dialog[open]')){document.querySelector('dialog[open]').close();return}if(route().page==='home')return;const target=backPath();if(history.state?.from==='#'+target)history.back();else go(target)}
function quizProgress(step){return `<div class="quiz-progress" aria-label="Шаг ${step} из 3">${['Услуга','Маршрут и груз','Контакт'].map((v,i)=>`<span class="${i+1<=step?'on':''}">${v}</span>`).join('')}</div>`}
function home(){if(role==='manager')return orders();const resume=db.draft.address||db.draft.cargo;return `<div class="page narrow quiz-home">${quizProgress(1)}<div class="hero-label">БЕЛАРУСЬ · РОССИЯ</div><h1 class="quiz-title">Ваш груз —<br>наша забота.</h1><p class="home-copy">Выберите услугу. Остальное согласуем.</p>${resume?'<button class="resume-draft secondary" data-go="request">Продолжить заявку →</button>':''}<div class="quiz-options" role="radiogroup" aria-label="Услуга">${[['hydro','hydrolift.webp','Гидроборт','Погрузка, перевозка и разгрузка','70 BYN/час · от 3 часов'],['freight','freight.webp','Беларусь — Россия','Минск — Москва и другие маршруты','Индивидуальный расчёт']].map(([t,img,title,desc,rate])=>`<button class="quiz-option fleet ${db.taskChoice===t?'selected':''}" data-task="${t}" role="radio" aria-checked="${db.taskChoice===t}"><img src="assets/${img}" alt="" width="84" height="84"><span><b>${title}</b><small>${desc}</small><strong>${rate}</strong></span><span class="choice-check" aria-hidden="true">✓</span></button>`).join('')}</div><div class="actions home-actions"><button class="primary" id="task-next" ${db.taskChoice?'':'disabled'}>Далее: маршрут и груз →</button><button class="example-button" id="preview-example">Попробовать на примере</button><span class="small muted">Демо · без реальной отправки заявки</span></div></div>`}
function field(name,title,placeholder='',extra='',value=db.draft[name]){return `<label class="field"><span>${title}</span><input name="${name}" value="${esc(value)}" placeholder="${placeholder}" ${extra}></label>`}
function photos(list,editable=false){return `<div class="photo-strip">${list.map((p,i)=>`<div class="photo"><img src="${esc(p.data)}" alt="Фото ${i+1}: ${esc(p.name)}" data-photo="${i}" tabindex="0" role="button">${editable?`<button type="button" class="remove" data-remove-photo="${i}" aria-label="Удалить фото ${i+1}">×</button>`:''}</div>`).join('')}${editable&&list.length<3?`<label class="upload"><b>＋</b><span>${photoBusy?'Подготовка…':'Добавить фото'}</span><input type="file" accept="image/*" multiple id="photo-input" ${photoBusy?'disabled':''}></label>`:''}</div>`}
function requestForm(screen=route()){const d=db.draft,contact=screen.id==='contact';return `<div class="page narrow quiz-page">${quizProgress(contact?3:2)}<div class="quiz-heading"><h1 class="quiz-title">${contact?'Куда сообщить стоимость?':'Куда везём груз?'}</h1><button type="button" class="example-button" id="fill-request">Заполнить примером</button></div><form id="${contact?'request-form':'details-form'}">${contact?`<div class="fields contact-fields">${field('phone','Телефон','+375 (29) 123-45-67','required type="tel" inputmode="tel" autocomplete="tel" maxlength="25"')}${field('name','Имя · необязательно','Как к вам обращаться','maxlength="60" autocomplete="given-name"')}</div><section class="review"><div class="review-heading"><b>Ваша заявка</b><button type="button" class="text-btn" data-go="request">Изменить</button></div><p>${types[d.type]}</p><p>${esc(d.address)} → ${esc(d.destination)}</p><p>${esc(d.cargo)}</p><p>${d.day?niceDay(d.day)+(d.time?' · '+esc(d.time):''):'Дату согласуем'}</p>${d.photos.length?`<p>Фото груза: ${d.photos.length}</p>`:''}</section>${estimateHTML(d)}<p class="small muted submit-note">Демо · данные останутся в этом браузере.</p>`:`<p class="selected-machine">${types[d.type]} <button type="button" class="text-btn" data-go="home">Изменить</button></p><div class="fields cargo-fields"><div class="full">${field('address','Откуда','Город, улица, дом','required minlength="5" maxlength="250"')}</div><div class="full">${field('destination','Куда','Город, улица, дом','required minlength="5" maxlength="250"')}</div><div class="full">${field('cargo','Что перевозим','Например, оборудование на двух паллетах','required minlength="3" maxlength="250"')}</div>${field('weight','Вес, кг · если известен','Например, 800','type="number" min="0.1" max="1000000" step="any" inputmode="decimal"')}${field('volume','Объём, м³ · если известен','Например, 4','type="number" min="0.01" max="10000" step="any" inputmode="decimal"')}<div class="full schedule-fields"><span class="field-label">Когда нужна перевозка?</span><div class="date-shortcuts">${[['today','Сегодня'],['tomorrow','Завтра'],['later','Согласуем']].map(([k,label])=>`<button type="button" class="secondary" data-day="${k}" aria-pressed="${k==='today'?d.day===localDay():k==='tomorrow'?d.day===tomorrowDay():!d.day}">${label}</button>`).join('')}</div><label class="date-control"><span>${d.day?niceDay(d.day):'Выбрать другую дату'}</span><span aria-hidden="true">▦</span><input name="day" type="date" value="${esc(d.day)}" min="${localDay()}" aria-label="Выбрать дату"></label>${d.day?`<label class="field time-control"><span>Время погрузки</span><select name="time">${['',...Array.from({length:32},(_,i)=>String(6+Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00'))].map(t=>`<option value="${t}" ${d.time===t?'selected':''}>${t||'Согласуем'}</option>`).join('')}</select></label>`:''}</div>${d.type==='hydro'?`${field('hours','Часы работы · минимум 3','3','required type="number" min="3" max="72" step="1" inputmode="numeric"')}${field('km','Пробег за МКАД, км','0','required type="number" min="0" max="10000" step="any" inputmode="decimal"')}<div class="full">${estimateHTML(d)}</div>`:''}</div><details class="optional-details" ${d.detailsOpen?'open':''}><summary>Комментарий и фото · необязательно <span>＋</span></summary><div class="optional-body"><label class="field"><span>Особенности груза</span><textarea name="comment" maxlength="1500" placeholder="Размеры, упаковка, хрупкость, нужна ли помощь с погрузкой">${esc(d.comment)}</textarea></label><label class="field"><span>Условия подъезда</span><textarea name="access" maxlength="1000" placeholder="Этаж, рампа, ограничения въезда">${esc(d.access)}</textarea></label>${photos(d.photos,true)}</div></details>`}<div id="form-error" class="error" role="alert"></div></form></div>`}
function niceDay(day){return new Date(day+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function tomorrowDay(){const d=new Date();d.setDate(d.getDate()+1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function localDay(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function brief(o){return `<section class="summary"><h3>Детали перевозки</h3>${[['Услуга',types[o.type]],['Откуда',o.address],['Куда',o.destination],['Груз',o.cargo],['Вес / объём',[o.weight?o.weight+' кг':'',o.volume?o.volume+' м³':''].filter(Boolean).join(' / ')||'Уточним'],['Погрузка',o.day?niceDay(o.day)+(o.time?' · '+o.time:''):'Дату согласуем'],...(o.type==='hydro'?[['Работа',o.hours+' ч'],['За МКАД',o.km+' км'],['Ориентир',fmt(estimate(o))+' BYN']]:[]),['Комментарий',o.comment||'Не указан'],['Подъезд',o.access||'Уточним'],['Клиент',o.name||'Имя не указано'],['Телефон',o.phone]].map(([k,v])=>`<div class="data-row"><span>${k}</span><span>${esc(v)}</span></div>`).join('')}${photos(o.photos)}</section>`}
function orders(){const list=db.orders.slice().sort((a,b)=>b.created-a.created);return `<div class="page narrow"><div class="list-heading"><h1 class="page-title">${role==='manager'?'Заявки на оценку':'Мои заявки'}</h1><span class="list-count">${list.length}</span></div>${list.length?list.map(o=>`<button class="order" data-go="order/${o.id}"><div class="order-top"><span class="small muted">№ TL-${o.id}</span>${badge(o)}</div><h3>${types[o.type]}</h3><p class="small">${esc(o.cargo)}</p><p class="small muted">${esc(o.address)} → ${esc(o.destination)}<br>${o.day?niceDay(o.day):'Дата уточняется'}${o.time?' · '+esc(o.time):''}</p>${o.offer?`<div class="manager-next">${fmt(o.offer.options[0].price)} BYN · ${o.accepted!=null?'Клиент принял условия':'Ожидаем решения клиента'}</div>`:'<div class="manager-next needs-action">Ожидает оценки менеджером →</div>'}</button>`).join(''):`<div class="empty"><h2>Пока нет заявок</h2><p>Здесь будут ваши заявки и предложения по стоимости.</p><button class="primary" data-role="client" data-go="home">Создать заявку →</button></div>`}</div>`}

function quoteDraft(o){if(!db.quotes[o.id])db.quotes[o.id]={options:[{name:'',price:'',note:''}],comment:''};return db.quotes[o.id]}
function quoteForm(o){const q=quoteDraft(o);q.type??=o.type;q.options[0].name=types[q.type||o.type];return `<form id="quote-form" class="offer-form manager-quote"><h2>Предложить стоимость</h2><p class="small muted">Оцените маршрут, параметры груза и условия погрузки.</p><button type="button" class="manager-example" id="fill-quote">Заполнить примером</button>${field('qprice0','Итого за заказ, BYN','0','required type="number" min="0.01" max="999999" step="0.01" inputmode="decimal"',q.options[0].price)}<label class="field manager-comment"><span>Что входит и условия перевозки</span><textarea name="qcomment" maxlength="1500" required placeholder="Укажите состав работ и условия">${esc(q.comment)}</textarea></label><p class="small muted">Цена в примере условная, не прайс компании.</p><button class="primary manager-send" type="submit">Предложить цену <span>→</span></button></form>`}
function managerThread(o){const body=`${o.messages.map(m=>`<div class="message ${m.role===role?'mine':''}"><small>${m.role==='client'?esc(o.name):'Менеджер'} · ${date(m.at)}</small>${esc(m.text)}</div>`).join('')}<form class="chat-form" id="chat-form"><label class="sr" for="chat-text">${role==='client'?'Сообщение менеджеру':'Сообщение клиенту'}</label><textarea id="chat-text" name="message" required maxlength="1500" placeholder="${role==='client'?'Задать вопрос менеджеру…':'Написать клиенту…'}">${esc(db.chats[o.id+'-'+role]||'')}</textarea><button type="submit" aria-label="Отправить сообщение">↑</button></form>`;return o.messages.length?`<section class="thread manager-thread"><h2>Переписка</h2>${body}</section>`:`<details class="manager-chat"><summary>${role==='client'?'Задать вопрос менеджеру':'Написать клиенту'} <span>＋</span></summary>${body}</details>`}
function managerOffer(o){return `<section class="manager-result"><h2>${o.accepted!=null?'Клиент принял условия':o.status==='question'?'Клиент задал вопрос':'Цена предложена'}</h2><p class="small muted">${o.accepted!=null?'Свяжитесь с клиентом для согласования перевозки.':'Ожидаем решения клиента.'}</p><div class="manager-offer-row"><strong>${types[o.type]}</strong><b>${fmt(o.offer.options[0].price)} <small>BYN</small></b></div><p class="sent-comment">${esc(o.offer.comment)}</p></section>`}
function managerDetail(o){return `<div class="page narrow manager-page"><p class="small muted">Режим менеджера</p><div class="detail-head"><span class="small muted">№ TL-${o.id}</span>${badge(o)}</div><h1 class="page-title">${types[o.type]}</h1>${brief(o)}${o.offer?managerOffer(o):quoteForm(o)}${o.status==='accepted'?'<button class="primary" id="schedule">Согласовать перевозку ✓</button>':o.status==='scheduled'?'<button class="primary" id="complete">Завершить заказ ✓</button>':''}${managerThread(o)}</div>`}
function offer(o){return `<section class="price-panel"><span class="eyebrow muted">Предложение менеджера</span><h2>${fmt(o.offer.options[0].price)} <small>BYN</small></h2><p>${esc(o.offer.comment).replace(/\n/g,'<br>')}</p><p class="small muted">Демонстрационная цена. Без оплаты и реального бронирования.</p>${o.accepted==null?'<button class="primary" id="accept-price">Подходит, согласовать</button>':'<div class="notice"><strong>✓ Вы приняли условия</strong>Менеджер видит ваше решение.</div>'}</section>`}
function orderDetail(id){const o=db.orders.find(x=>x.id===id);if(!o)return `<div class="page narrow"><h1 class="page-title">Заявка не найдена</h1><button class="primary" data-go="orders">К заявкам</button></div>`;if(role==='manager')return managerDetail(o);const phase=o.accepted!=null?3:o.offer?2:1;return `<div class="page narrow"><div class="detail-head"><span class="small muted">№ TL-${o.id}</span>${badge(o)}</div><h1 class="page-title">${types[o.type]}</h1><div class="progress">${[1,2,3].map(i=>`<i class="${i<=phase?'on':''}"></i>`).join('')}</div><div class="progress-labels"><span>Оценка менеджером</span><span>Цена</span><span>Принятие условий</span></div>${o.offer?offer(o):'<div class="notice"><strong>Заявка на оценке</strong>После оценки здесь появятся цена и условия. Заказ пока не подтверждён.</div>'}${brief(o)}${managerThread(o)}</div>`}
function contacts(){return `<div class="page narrow"><h1 class="page-title">Всегда на связи</h1><p class="intro">Перевозки по Беларуси и России</p><section class="contact-panel"><span class="eyebrow">Transport Logistics</span><h2><a href="tel:+375447768306">+375 (44) 776-83-06</a></h2><p><a href="mailto:m1t1n.mit@yandex.by">m1t1n.mit@yandex.by</a></p><div class="rate"><span>Гидроборт · от 3 часов</span><b>70 BYN/час</b></div><div class="rate"><span>За пределами МКАД</span><b>1,8 BYN/км</b></div><div class="rate"><span>Беларусь — Россия</span><b>По запросу</b></div><a class="primary" href="tel:+375447768306">Позвонить</a><a class="secondary" href="https://transport-logistics.by" target="_blank" rel="noopener">Открыть сайт ↗</a><p class="small muted">Это демо. Для реального заказа свяжитесь с компанией.</p></section></div>`}
function pageHTML(r){return r.page==='home'?home():r.page==='request'?requestForm(r):r.page==='orders'?orders():r.page==='contacts'?contacts():r.page==='order'?orderDetail(r.id):home()}
function render(){const r=route();document.querySelectorAll('.roles [data-role]').forEach(b=>{b.classList.toggle('active',b.dataset.role===role);b.setAttribute('aria-pressed',String(b.dataset.role===role))});$('#main').innerHTML=pageHTML(r)+`<footer class="footer"><button data-go="contacts">Контакты</button><details class="demo-tools"><summary>Демо</summary><div><p>Только на этом устройстве. Реальных отправок нет.</p><button data-role="${role==='client'?'manager':'client'}">${role==='client'?'Открыть режим менеджера':'Вернуться к клиенту'}</button><button id="reset">Сбросить демо</button></div></details></footer>`;const dock=$('#flow-dock');dock.hidden=r.page!=='request';dock.innerHTML=r.page==='request'?`<button class="primary" type="submit" form="${r.id==='contact'?'request-form':'details-form'}" ${photoBusy?'disabled':''}>${r.id==='contact'?'Получить стоимость':'Далее: телефон'} →</button>`:'';$('.nav-back').hidden=r.page==='home';if(inTelegram&&telegram?.BackButton){if(r.page==='home')telegram.BackButton.hide();else telegram.BackButton.show();}$('.top').classList.toggle('home-header',r.page==='home');$('#header-count').textContent=db.orders.length||'';$('#tab-count').textContent=db.orders.length||'';document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===(['orders','order'].includes(r.page)?'orders':'home');if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('.roles').classList.toggle('manager',role==='manager');document.title=(r.page==='order'?'Заявка TL-'+r.id:r.page==='request'?types[db.draft.type]:role==='manager'?'Рабочее место':'Transport Logistics')+' — Демо'}
addEventListener('hashchange',e=>{edgeBack.cancel();scrolls.set(currentHash,$('#main').scrollTop);const previous=new URL(e.oldURL).hash;currentHash=location.hash;if(!history.state?.transport)history.replaceState({transport:true,from:previous},'');render();$('#main').scrollTop=scrolls.get(currentHash)||0;$('#main').focus({preventScroll:true})});
function rerenderKeep(){const y=$('#main').scrollTop;render();$('#main').scrollTop=y}
function currentOrder(){return db.orders.find(o=>o.id===route().id)}
function switchRole(next){role=next;db.role=role;persist();if(route().page==='request')go('home');else rerenderKeep()}
function start(type){if(db.draft.type!==type){db.draft.type=type}persist();go('request')}

function fillRequest(){Object.assign(db.draft,{exampleFilled:true,cargo:'Оборудование на двух паллетах',comment:'Груз упакован, нужна бережная перевозка.',address:'Минск, ул. Промышленная, 6',destination:db.draft.type==='freight'?'Москва, ул. Складочная, 1':'Минск, ул. Тимирязева, 65',weight:'800',volume:'4',day:tomorrowDay(),time:'10:00',hours:'3',km:'0',access:'Свободный подъезд, погрузка с уровня земли.',name:'Алексей',phone:'+375 (29) 000-00-00'});persist();rerenderKeep();toast('Тестовые данные заполнены')}
function fillQuote(){const o=currentOrder(),q=quoteDraft(o);q.options=[{name:types[o.type],price:String(o.type==='hydro'?estimate(o):1500),note:''}];q.comment=o.type==='hydro'?`Демо: ${o.hours} ч работы с гидробортом, пробег за МКАД — ${o.km} км. Погрузка ${o.day?niceDay(o.day):'по согласованию'}. Итоговые условия уточняются.`:'Условный пример: перевозка по указанному маршруту. Дата, состав услуг и документы согласуются отдельно.';persist();rerenderKeep();toast('Пример цены заполнен')}
function openPhoto(i){const list=route().page==='request'?db.draft.photos:currentOrder()?.photos;const p=list?.[i];if(p){$('#large-photo').src=p.data;$('#lightbox').showModal()}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,[data-photo]');if(!b)return;if(b.id==='preview-example'){db.draft.type=db.taskChoice||'hydro';db.taskChoice=db.draft.type;fillRequest();go('request');return}if(b.dataset.day){db.draft.day=b.dataset.day==='today'?localDay():b.dataset.day==='tomorrow'?tomorrowDay():'';if(!db.draft.day)db.draft.time='';persist();rerenderKeep();return}if(b.dataset.go){if(b.dataset.role)switchRole(b.dataset.role);go(b.dataset.go);return}if(b.dataset.role){switchRole(b.dataset.role);return}if(b.dataset.start){start(b.dataset.start);return}if(b.dataset.task){db.taskChoice=b.dataset.task;persist();document.querySelectorAll('[data-task]').forEach(el=>{const selected=el.dataset.task===db.taskChoice;el.classList.toggle('selected',selected);el.setAttribute('aria-checked',String(selected));});$('#task-next').disabled=false;return}if(b.id==='task-next'){if(db.taskChoice)start(db.taskChoice);return}if(b.hasAttribute('data-back')){back();return}if(b.hasAttribute('data-close')){b.closest('dialog').close();return}if(b.hasAttribute('data-photo')){openPhoto(+b.dataset.photo);return}if(b.hasAttribute('data-remove-photo')){db.draft.photos.splice(+b.dataset.removePhoto,1);persist();rerenderKeep();return}if(b.hasAttribute('data-delete-option')){quoteDraft(currentOrder()).options.splice(+b.dataset.deleteOption,1);persist();rerenderKeep();return}switch(b.id){case 'fill-request':fillRequest();break;case 'fill-quote':fillQuote();break;case 'add-option':{const q=quoteDraft(currentOrder());if(q.options.length<3)q.options.push({name:'',price:'',note:''});persist();rerenderKeep();break}case 'accept-offer':{const o=currentOrder();if(!Number.isInteger(o.choice)){const el=$('#choice-error');el.textContent='Выберите один из предложенных вариантов.';document.querySelector('input[name="chosen"]')?.focus();break}const old=o.status;o.accepted=o.choice;o.status='accepted';if(!persist()){delete o.accepted;o.status=old;break}rerenderKeep();toast('Выбор сохранён. Менеджер увидит ваше решение.');break}case 'reset':$('#reset-dialog').showModal();break;case 'confirm-reset':$('#reset-dialog').close();db={orders:[],draft:blankDraft(),quotes:{},chats:{},role:'client'};role='client';persist();scrolls.clear();go('home');toast('Демонстрационные данные сброшены');break}});
document.addEventListener('toggle',e=>{if(e.target.matches('.optional-details')){db.draft.detailsOpen=e.target.open;persist()}},true);
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.hasAttribute('data-photo')){e.preventDefault();openPhoto(+e.target.dataset.photo)}});
document.addEventListener('input',e=>{const t=e.target,n=t.name;if(t.closest('#request-form, #details-form')&&n&&n!=='feature'){db.draft[n]=t.value;persist();if(['hours','km'].includes(n)&&$('#estimate-total')){$('#estimate-total').innerHTML=fmt(estimate(db.draft))+' <small>BYN</small>';$('#estimate-hours').textContent=db.draft.hours;$('#estimate-km').textContent=db.draft.km}}if(t.closest('#quote-form')){const q=quoteDraft(currentOrder());if(n==='qcomment')q.comment=t.value;else if(n==='qtype')q.type=t.value;else {const m=n.match(/^q(name|price|note)(\d+)$/);if(m)q.options[+m[2]][m[1]]=t.value}persist()}if(t.id==='chat-text'){db.chats[route().id+'-'+role]=t.value;persist()}});
document.addEventListener('change',e=>{const t=e.target;if(t.name==='day'){db.draft.day=t.value;if(!t.value)db.draft.time='';persist();rerenderKeep()}if(t.name==='time'){db.draft.time=t.value;persist()}if(t.name==='qtype'){quoteDraft(currentOrder()).type=t.value;persist()}if(t.name==='chosen'){currentOrder().choice=+t.value;persist()}if(t.id==='photo-input')handlePhotos([...t.files])});
async function compressPhoto(file){if(!file.type.startsWith('image/'))throw Error('Выберите файл изображения.');if(file.size>25*1024*1024)throw Error('Фото больше 25 МБ. Выберите файл поменьше.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Не удалось открыть фото. Выберите JPEG, PNG или WebP.'));im.src=url});const scale=Math.min(1,1200/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);return {name:file.name,data:c.toDataURL('image/jpeg',.72)}}finally{URL.revokeObjectURL(url)}}
async function handlePhotos(files){if(photoBusy)return;const draft=db.draft;photoBusy=true;rerenderKeep();if(files.length>3-draft.photos.length)toast('Можно добавить до трёх фотографий.');for(const f of files.slice(0,3-draft.photos.length)){try{const p=await compressPhoto(f);if(db.draft!==draft)break;draft.photos.push(p);if(!persist())draft.photos.pop()}catch(err){toast(err.message)}}photoBusy=false;if(route().page==='request')rerenderKeep()}
document.addEventListener('submit',e=>{if(e.target.id==='details-form'||e.target.id==='request-form'){e.preventDefault();if(photoBusy)return;const d=db.draft;if(!['hydro','freight'].includes(d.type)||d.address.trim().length<5||d.destination.trim().length<5||d.cargo.trim().length<3||(d.day&&d.day<localDay())||(d.type==='hydro'&&(!Number.isInteger(+d.hours)||+d.hours<3||+d.hours>72||!Number.isFinite(+d.km)||+d.km<0||+d.km>10000))){$('#form-error').textContent='Укажите маршрут и груз, проверьте дату. Для гидроборта — от 3 до 72 часов и неотрицательный пробег.';return}if(e.target.id==='details-form'){go('request/contact');return}const phone=d.phone.replace(/\D/g,'');if(!/^\+?[1-9]\d{8,14}$/.test(d.phone.replace(/[\s()-]/g,''))){$('#form-error').textContent='Проверьте телефон: например, +375 29 123-45-67.';return}const id=String(Math.max(1000,...db.orders.map(o=>+o.id))+1),o={...JSON.parse(JSON.stringify(d)),id,created:Date.now(),status:'new',messages:[]};db.orders.push(o);const old=db.draft;db.draft=blankDraft();if(!persist()){db.orders.pop();db.draft=old;return}go('order/'+id);toast('Демо-заявка TL-'+id+' создана')}else if(e.target.id==='quote-form'){e.preventDefault();const o=currentOrder(),q=quoteDraft(o);if(!Number.isFinite(+q.options[0].price)||+q.options[0].price<=0||!q.comment.trim()){toast('Укажите цену и условия.');return}const old=o.status,oldType=o.type;q.options[0].name=types[o.type];o.offer={options:q.options.map(v=>({...v,price:+v.price})),comment:q.comment,sent:Date.now()};o.status='offer';if(!persist()){delete o.offer;o.status=old;o.type=oldType;return}rerenderKeep();toast('Предложение сохранено. Переключитесь к клиенту.')}else if(e.target.id==='chat-form'){e.preventDefault();const o=currentOrder(),t=$('#chat-text').value.trim();if(!t)return;const old=o.status;o.messages.push({role,text:t,at:Date.now()});if(role==='client'&&o.accepted==null)o.status='question';else if(role==='manager'&&o.accepted==null)o.status=o.offer?'offer':'new';const k=o.id+'-'+role,oldDraft=db.chats[k];delete db.chats[k];if(!persist()){o.messages.pop();o.status=old;db.chats[k]=oldDraft;return}rerenderKeep();toast('Сообщение сохранено в демо')}});
document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(!['accept-price','schedule','complete'].includes(id))return;const o=currentOrder();if(!o)return;const old=o.status;if(id==='accept-price'&&role==='client'&&o.offer&&o.accepted==null){o.accepted=0;o.status='accepted'}else if(id==='schedule'&&role==='manager'&&o.status==='accepted')o.status='scheduled';else if(id==='complete'&&role==='manager'&&o.status==='scheduled')o.status='completed';else return;if(!persist()){o.status=old;if(id==='accept-price')delete o.accepted;return}rerenderKeep();toast('Статус обновлён в демо')});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});

addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);db.orders=next.orders;db.quotes=next.quotes;rerenderKeep()}catch{}}});

function updateViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--app-height',(v?v.height:innerHeight)+'px');const focused=document.activeElement?.matches('input,textarea,select');document.documentElement.classList.toggle('keyboard-open',!!focused&&!!v&&innerHeight-v.height>120);if(focused)setTimeout(()=>document.activeElement?.scrollIntoView({block:'nearest'}),80)}
let telegram=window.Telegram?.WebApp;const inTelegram=!!telegram?.initData||/tgWebApp(Data|Platform|Version)=/.test(location.search+location.hash)||!!window.TelegramWebviewProxy||!!window.TelegramWebviewProxyProto||!!window.TelegramGameProxy;
document.documentElement.dataset.telegram=String(inTelegram);
function updateSafeArea(){const root=document.documentElement;for(const [source,prefix] of [[telegram?.safeAreaInset,'safe'],[telegram?.contentSafeAreaInset,'content']]){if(source)for(const side of ['top','bottom'])if(Number.isFinite(source[side]))root.style.setProperty('--native-'+prefix+'-'+side,source[side]+'px')}}
function connectTelegram(){telegram=window.Telegram?.WebApp;if(!inTelegram||!telegram)return;updateSafeArea();try{telegram.ready();telegram.expand();telegram.BackButton?.onClick(back);telegram.setHeaderColor('#f5f5f2');telegram.setBackgroundColor('#f5f5f2');if(telegram.isVersionAtLeast?.('8.0')&&!telegram.isFullscreen)telegram.requestFullscreen()}catch{}if(telegram.onEvent){telegram.onEvent('safeAreaChanged',updateSafeArea);telegram.onEvent('contentSafeAreaChanged',updateSafeArea);telegram.onEvent('viewportChanged',updateViewport);telegram.onEvent('fullscreenChanged',()=>{updateSafeArea();updateViewport()})}}
connectTelegram();if(inTelegram&&!telegram){const script=document.createElement('script');script.src='https://telegram.org/js/telegram-web-app.js';script.onload=connectTelegram;document.head.append(script)}
window.visualViewport?.addEventListener('resize',updateViewport);addEventListener('resize',updateViewport);document.addEventListener('focusin',updateViewport);document.addEventListener('focusout',()=>setTimeout(updateViewport,100));updateViewport();
const edgeBack=(()=>{const app=$('#app'),view=$('#main');let drag=null,stage=null,front=null,rear=null,shade=null,timer=null,suppressUntil=0;
function cancel(){clearTimeout(timer);stage?.remove();app.classList.remove('edge-dragging');drag=stage=front=rear=shade=null}
function strip(el){el.removeAttribute('id');el.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));el.querySelectorAll('[autofocus]').forEach(n=>n.removeAttribute('autofocus'));el.inert=true;return el}
function prepare(){const path=backPath(),[page,id]=path.split('/');stage=document.createElement('div');stage.className='edge-stage';stage.setAttribute('aria-hidden','true');function frame(previous){const screen=document.createElement('div');screen.className='edge-screen'+(previous?'':' front');const snapshot=strip(app.cloneNode(true));snapshot.classList.remove('edge-dragging');snapshot.querySelectorAll('.edge-stage').forEach(el=>el.remove());const content=snapshot.querySelector('.app-view');if(previous){content.innerHTML=pageHTML({page,id})+`<footer class="footer"><button>Контакты сервиса</button><button>Сбросить демо</button></footer>`;snapshot.querySelector('.nav-back').hidden=page==='home';snapshot.querySelector('.top').classList.toggle('home-header',page==='home');strip(content)}screen.append(snapshot);return {screen,content}}const previous=frame(true),visible=frame(false);rear=previous.screen;front=visible.screen;shade=document.createElement('div');shade.className='edge-shade';rear.append(shade);stage.append(rear,front);app.append(stage);previous.content.scrollTop=scrolls.get('#'+path)||0;visible.content.scrollTop=view.scrollTop;app.classList.add('edge-dragging');move(0)}

function move(x){front.style.transform=`translate3d(${x}px,0,0)`;rear.style.transform=`translate3d(${(x-drag.width)*.24}px,0,0)`;shade.style.opacity=String(.16*(1-x/drag.width))}
function finish(commit){if(!stage)return cancel();drag.settling=true;suppressUntil=performance.now()+450;const ms=matchMedia('(prefers-reduced-motion: reduce)').matches?0:220;front.style.transition=rear.style.transition=`transform ${ms}ms cubic-bezier(.2,.75,.25,1)`;shade.style.transition=`opacity ${ms}ms ease`;move(commit?drag.width:0);timer=setTimeout(()=>{cancel();if(commit)back()},ms)}
app.addEventListener('touchstart',e=>{if(drag||route().page==='home'||photoBusy||document.querySelector('dialog[open]')||e.touches.length!==1)return;const t=e.touches[0],r=app.getBoundingClientRect();if(t.clientX<r.left||t.clientX>r.left+28||t.clientY<r.top||e.target.closest('input,textarea,select,.roles'))return;drag={id:t.identifier,x:t.clientX,y:t.clientY,width:r.width,distance:0,active:false,settling:false}},{passive:true});
app.addEventListener('touchmove',e=>{if(!drag||drag.settling)return;if(e.touches.length!==1)return cancel();const t=[...e.touches].find(t=>t.identifier===drag.id);if(!t)return;const dx=t.clientX-drag.x,dy=t.clientY-drag.y;if(!drag.active){if(Math.abs(dy)>8&&Math.abs(dy)>=Math.abs(dx)||dx< -8)return cancel();if(dx<8||dx<Math.abs(dy)*1.2)return;if(!e.cancelable)return cancel();drag.active=true;document.activeElement?.blur();prepare()}if(e.cancelable)e.preventDefault();drag.distance=Math.max(0,Math.min(drag.width,dx));move(drag.distance)},{passive:false});
app.addEventListener('touchend',e=>{if(!drag||drag.settling||![...e.changedTouches].some(t=>t.identifier===drag.id))return;if(!drag.active)return cancel();if(e.cancelable)e.preventDefault();finish(drag.distance>=drag.width*.35)},{passive:false});app.addEventListener('touchcancel',()=>drag?.active&&!drag.settling?finish(false):cancel(),{passive:true});app.addEventListener('click',e=>{if(performance.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation()}},true);addEventListener('resize',cancel);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel()});return {cancel}})();
if(!location.hash)history.replaceState(null,'','#home');currentHash=location.hash;render();

function estimate(d){return 70*Number(d.hours||3)+1.8*Number(d.km||0)}
function estimateHTML(d){return d.type==='hydro'?`<section class="estimate"><span>Предварительный расчёт</span><strong id="estimate-total">${fmt(estimate(d))} <small>BYN</small></strong><p>70 BYN/час × <span id="estimate-hours">${esc(d.hours)}</span> ч + 1,8 BYN/км × <span id="estimate-km">${esc(d.km)}</span> км за МКАД.</p><p>Итоговую стоимость, оплачиваемый пробег и условия подтвердит менеджер.</p></section>`:'<div class="notice">Стоимость перевозки рассчитывается индивидуально по маршруту и параметрам груза.</div>'}
